# -*- coding: utf-8 -*-
"""Тесты-самопроверки Т1 для «Как здорово!» 7–9 (07.11.2026). Ключи на странице (grading: client) — это тренировка, не контрольная.
Запуск: python3 tools/build_tests_kz79.py  → tests/kz7-t1-1107.json, kz8-…, kz9-… и строки в tests/index.json."""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
def opts(*o): return '<ol class="opts">' + ''.join(f'<li>{x}</li>' for x in o) + '</ol>'
def one(q, o, key, topic): return dict(kind='one', pts=1, key=key, topic=topic, text=f'<p>{q}</p>' + opts(*o))
def num(q, key, unit, topic, tol=0.01): return dict(kind='num', pts=1, key=key, tol=tol, unit=unit, topic=topic, text=f'<p>{q}</p>')
SRC = {'author': 'учитель', 'note': 'самопроверка к уроку 07.11.2026'}
TESTS = {
 'kz7-t1-1107': dict(cls=7, title='7 класс · Средняя скорость, инерция, масса · самопроверка',
   ref='<p><b>Формулы:</b> v<sub>ср</sub> = s<sub>весь</sub> / t<sub>всё</sub>; m₁/m₂ = v₂/v₁. <b>Единицы:</b> 1 т = 1000 кг, 1 г = 0,001 кг, 1 ч = 60 мин.</p>',
   tasks=[one('Средняя скорость — это…', ['среднее арифметическое скоростей', 'весь путь, делённый на всё время движения', 'наибольшая скорость на пути', 'скорость в конце пути'], 2, 'средняя скорость'),
          num('Велосипедист проехал 12 км за 40 мин, отдохнул 20 мин и проехал ещё 6 км за 20 мин. Найдите среднюю скорость за всё время.', 13.5, 'км/ч', 'средняя скорость'),
          num('Туристы шли 2 ч со скоростью 5 км/ч, а затем 1 ч со скоростью 2 км/ч. Найдите среднюю скорость.', 4, 'км/ч', 'средняя скорость'),
          one('Какой пример — проявление инерции?', ['мяч падает на землю', 'при торможении автобуса пассажиры наклоняются вперёд', 'лёд тает на солнце', 'стрелка компаса поворачивается к северу'], 2, 'инерция'),
          one('Мерой инертности тела является…', ['скорость', 'объём', 'масса', 'путь'], 3, 'масса'),
          num('Выразите 0,25 т в килограммах.', 250, 'кг', 'единицы массы'),
          num('Две тележки оттолкнулись друг от друга. Первая тележка массой 2 кг получила скорость 0,3 м/с, вторая — 0,6 м/с. Найдите массу второй тележки.', 1, 'кг', 'сравнение масс'),
          num('Мальчик массой 60 кг прыгнул с неподвижной лодки со скоростью 2 м/с, а лодка откатилась со скоростью 1,5 м/с. Найдите массу лодки.', 80, 'кг', 'сравнение масс')]),
 'kz8-t1-1107': dict(cls=8, title='8 класс · Плавление и кристаллизация · самопроверка',
   ref='<p><b>Формулы:</b> Q = λm; Q = cmΔt. <b>λ, Дж/кг:</b> лёд 340 000, алюминий 390 000, железо 270 000, медь 210 000, олово 59 000, свинец 25 000. <b>c льда</b> = 2100 Дж/(кг·°C).</p>',
   tasks=[one('Кристаллизация (отвердевание) — это переход вещества…', ['из твёрдого состояния в жидкое', 'из жидкого состояния в твёрдое', 'из жидкого состояния в газ', 'из газа в твёрдое'], 2, 'определения'),
          one('Какое из этих тел — аморфное?', ['лёд', 'поваренная соль', 'стекло', 'алюминий'], 3, 'кристаллы и аморфные тела'),
          one('Пока лёд плавится, его температура…', ['растёт', 'понижается', 'не меняется', 'сначала растёт, потом понижается'], 3, 'график плавления'),
          num('Олово плавится при 232 °C. При какой температуре оно отвердевает?', 232, '°C', 'температура плавления'),
          num('Сколько теплоты нужно, чтобы расплавить 4 кг железа, взятого при температуре плавления? Ответ дайте в килоджоулях.', 1080, 'кДж', 'Q = λm'),
          num('При отвердевании свинца, взятого при температуре плавления, выделилось 50 кДж теплоты. Найдите массу свинца.', 2, 'кг', 'Q = λm'),
          num('Для плавления 0,5 кг металла при температуре плавления потребовалось 105 кДж. Найдите удельную теплоту плавления в кДж/кг.', 210, 'кДж/кг', 'Q = λm'),
          num('Сколько теплоты нужно, чтобы 2 кг льда при −10 °C нагреть до 0 °C и полностью расплавить? Ответ дайте в килоджоулях.', 722, 'кДж', 'нагревание и плавление')]),
 'kz9-t1-1107': dict(cls=9, title='9 класс · Сложение сил, второй закон Ньютона · самопроверка',
   ref='<p><b>Формулы:</b> R<sub>x</sub> = F<sub>1x</sub> + F<sub>2x</sub> + …; при F₁ ⟂ F₂: R = √(F₁² + F₂²); a = R/m; a = (v − v₀)/t. 1 Н = 1 кг·м/с².</p>',
   tasks=[num('Две силы 7 Н и 3 Н направлены вдоль одной прямой в противоположные стороны. Найдите модуль равнодействующей.', 4, 'Н', 'сложение сил'),
          num('Две силы 5 Н и 12 Н направлены перпендикулярно друг другу. Найдите модуль равнодействующей.', 13, 'Н', 'сложение сил'),
          one('Тело движется по прямой с постоянной скоростью. Равнодействующая всех сил, приложенных к телу,…', ['направлена по скорости', 'равна нулю', 'направлена против скорости', 'направлена вертикально'], 2, 'I закон Ньютона'),
          num('Тележка массой 4 кг движется с ускорением 0,5 м/с². Найдите равнодействующую сил.', 2, 'Н', 'II закон Ньютона'),
          num('На тело массой 0,2 кг действует равнодействующая сила 3 Н. Найдите ускорение тела.', 15, 'м/с²', 'II закон Ньютона'),
          num('Мотоцикл массой 200 кг разгоняется из состояния покоя до скорости 20 м/с за 8 с. Найдите равнодействующую сил.', 500, 'Н', 'II закон + кинематика'),
          num('Ящик массой 10 кг тянут по полу с силой 70 Н, сила трения 30 Н. Найдите ускорение ящика.', 4, 'м/с²', 'II закон Ньютона'),
          one('Масса тела уменьшилась в 3 раза, а равнодействующая не изменилась. Ускорение тела…', ['уменьшилось в 3 раза', 'не изменилось', 'увеличилось в 3 раза', 'увеличилось в 9 раз'], 3, 'II закон Ньютона')]),
}
idx_path = os.path.join(ROOT, 'tests', 'index.json'); idx = json.load(open(idx_path, encoding='utf-8'))
for tid, t in TESTS.items():
    tasks = []
    for i, x in enumerate(t['tasks'], 1):
        x = dict(n=i, **x, source=SRC, bank_id=None, tid=f'{tid}-{i:02d}'); tasks.append(x)
    d = dict(version=1, exam=None, subject='физика', **{'class': t['cls']}, eyebrow=f'физика · {t["cls"]} класс · самопроверка',
             scale={'max': 8, 'grades': [[7, '5'], [5, '4'], [3, '3']], 'note': 'Самопроверка: «5» — от 7, «4» — от 5, «3» — от 3 баллов.'},
             reference=t['ref'], links=[], blocks=[{'title': 'Задания', 'auto': True, 'tasks': tasks}], id=tid, type='exam-topic', title=t['title'],
             check_mode='on_demand', attempts=0, timer=None, trainer=tid, sheet=t['title'],
             intro='Проверяйте ответ после каждого задания — можно исправлять и проверять снова. Ответ — номер варианта или число (десятичная запятая или точка).',
             grading='client')
    json.dump(d, open(os.path.join(ROOT, 'tests', tid + '.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    idx['tests'] = [x for x in idx['tests'] if x['id'] != tid] + [dict(id=tid, type='exam-topic', title=t['title'], **{'class': t['cls']}, exam=None)]
json.dump(idx, open(idx_path, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('ok', list(TESTS))
